import Foundation
import HuggingFace
import Replay
import Testing

@Suite("Hub tags replay", .serialized, .playbackIsolated(replaysFrom: Bundle.module))
struct TagsReplayTests {
    #if canImport(FoundationNetworking)
        // Linux URLProtocol does not receive the session header used by test scope.
        private static let replayScope: ReplayScope = .global
    #else
        // Global registration can intercept concurrent Xet requests through URLSession.shared.
        private static let replayScope: ReplayScope = .test
    #endif

    private var client: HubClient {
        HubClient(
            session: Replay.session,
            host: URL(string: "https://huggingface.co")!,
            bearerToken: nil,
            cache: nil
        )
    }

    private static func filters(keeping selection: [String: Set<String>]) -> [Filter] {
        [
            .custom { entry in
                var entry = entry
                let headers = ["authorization", "proxy-authorization", "cookie", "set-cookie"]
                entry.request.headers.removeAll { headers.contains($0.name.lowercased()) }
                entry.response.headers.removeAll { headers.contains($0.name.lowercased()) }
                entry.request.cookies = []
                entry.response.cookies = []
                // Keep complete entries and the API's top-level group structure.
                guard let text = entry.response.content.text,
                    entry.response.content.encoding == nil,
                    let groups = try? JSONSerialization.jsonObject(with: Data(text.utf8))
                        as? [String: [[String: Any]]]
                else {
                    Issue.record("Expected an unwrapped JSON object of tag groups when recording.")
                    return entry
                }
                var reduced: [String: [[String: Any]]] = [:]
                for (group, ids) in selection {
                    if let entries = groups[group] {
                        reduced[group] = entries.filter { tag in
                            guard let id = tag["id"] as? String else { return false }
                            return ids.contains(id)
                        }
                    }
                }
                guard let data = try? JSONSerialization.data(withJSONObject: reduced, options: [.sortedKeys]) else {
                    Issue.record("Could not encode reduced tag groups.")
                    return entry
                }
                entry.response.content.text = String(decoding: data, as: UTF8.self)
                entry.response.content.size = data.count
                entry.response.content.compression = nil
                entry.response.content.comment =
                    "Reduced recording: selected groups and tag IDs; complete entries retained."
                entry.response.bodySize = data.count
                entry.response.headersSize = -1
                let staleHeaders = ["content-length", "content-encoding", "etag", "content-md5", "digest"]
                entry.response.headers.removeAll { staleHeaders.contains($0.name.lowercased()) }
                return entry
            }
        ]
    }

    @Test(
        .replay(
            "model-tags",
            matching: [.method, .url],
            filters: filters(keeping: ["library": ["pytorch", "transformers"], "pipeline_tag": ["text-generation"]]),
            scope: replayScope
        )
    )
    func modelTags() async throws {
        let tags = try await client.getModelTags()
        let libraries = try #require(tags["library"])
        #expect(libraries.contains { $0.id == "pytorch" && $0.label == "PyTorch" })
        let tasks = try #require(tags["pipeline_tag"])
        #expect(tasks.contains { $0.id == "text-generation" })
    }

    @Test(
        .replay(
            "dataset-tags",
            matching: [.method, .url],
            filters: filters(keeping: ["library": ["library:datasets"], "language": ["language:en"]]),
            scope: replayScope
        )
    )
    func datasetTags() async throws {
        let tags = try await client.getDatasetTags()
        let libraries = try #require(tags["library"])
        #expect(libraries.contains { $0.id == "library:datasets" && !$0.label.isEmpty })
        let languages = try #require(tags["language"])
        #expect(languages.contains { $0.id == "language:en" })
    }
}

import Foundation
import Testing

import HuggingFace

// Like FileOperationsTests, these tests don't run on Linux: there,
// FoundationNetworking crashes in `_ProtocolClient.completeTask`
// when this test's URL protocol finishes loading a snapshot file.
#if !os(Linux)
    /// These tests build in Swift 5 language mode, where an unlabeled trailing
    /// closure can bind to the last closure parameter instead of the first.
    /// Existing calls like `downloadSnapshot(of:) { _ in ... }` must keep
    /// binding to `progressHandler`, not `fileProgressHandler`.
    @Suite("downloadSnapshot trailing closures in Swift 5 mode", .serialized)
    struct TrailingClosureTests {
        @Test("An unlabeled trailing closure binds to progressHandler")
        func unlabeledTrailingClosureBindsToProgressHandler() async throws {
            let (client, cacheDirectory) = makeClient()
            defer { try? FileManager.default.removeItem(at: cacheDirectory) }

            let recorder = ArgumentRecorder()
            // The closure type-checks against either handler, so only the
            // overload's parameter list decides which one it binds to.
            _ = try await client.downloadSnapshot(of: "user/model") { value in
                recorder.record(value)
            }

            #expect(!recorder.values.isEmpty)
            #expect(recorder.values.allSatisfy { $0 is Progress })
        }

        @Test("An unlabeled trailing closure binds to progressHandler with a destination")
        func unlabeledTrailingClosureBindsToProgressHandlerWithDestination() async throws {
            let (client, cacheDirectory) = makeClient()
            defer { try? FileManager.default.removeItem(at: cacheDirectory) }
            let destination = FileManager.default.temporaryDirectory
                .appendingPathComponent("hf-swift5-dest-\(UUID().uuidString)", isDirectory: true)
            defer { try? FileManager.default.removeItem(at: destination) }

            let recorder = ArgumentRecorder()
            _ = try await client.downloadSnapshot(of: "user/model", to: destination) { value in
                recorder.record(value)
            }

            #expect(!recorder.values.isEmpty)
            #expect(recorder.values.allSatisfy { $0 is Progress })
        }

        private func makeClient() -> (HubClient, URL) {
            let configuration = URLSessionConfiguration.ephemeral
            configuration.protocolClasses = [SnapshotURLProtocol.self]
            let cacheDirectory = FileManager.default.temporaryDirectory
                .appendingPathComponent("hf-swift5-cache-\(UUID().uuidString)", isDirectory: true)
            let client = HubClient(
                session: URLSession(configuration: configuration),
                host: URL(string: "https://huggingface.co")!,
                userAgent: "TestClient/1.0",
                bearerToken: "test_token",
                cache: HubCache(cacheDirectory: cacheDirectory)
            )
            return (client, cacheDirectory)
        }
    }

    private final class ArgumentRecorder: @unchecked Sendable {
        private let lock = NSLock()
        private var _values: [Any] = []

        func record(_ value: Any) {
            lock.lock()
            _values.append(value)
            lock.unlock()
        }

        var values: [Any] {
            lock.lock()
            defer { lock.unlock() }
            return _values
        }
    }

    /// Serves a one-file repository: its tree listing and `config.json`.
    private final class SnapshotURLProtocol: URLProtocol {
        override class func canInit(with request: URLRequest) -> Bool { true }
        override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }
        override func stopLoading() {}

        override func startLoading() {
            let url = request.url!
            let status: Int
            var headers: [String: String] = [:]
            var body = Data()
            if url.path.hasPrefix("/api/models/user/model/tree/main") {
                status = 200
                headers["Content-Type"] = "application/json"
                body = Data(#"[{"path": "config.json", "type": "file", "oid": "abc", "size": 11}]"#.utf8)
            } else if url.path == "/user/model/resolve/main/config.json" {
                status = 200
                if request.httpMethod == "HEAD" {
                    headers["ETag"] = "\"etag-config\""
                    headers["X-Repo-Commit"] = "1234567890123456789012345678901234567890"
                } else {
                    headers["Content-Type"] = "application/json"
                    body = Data(#"{"ok":true}"#.utf8)
                }
            } else {
                status = 404
            }
            let response = HTTPURLResponse(
                url: url,
                statusCode: status,
                httpVersion: "HTTP/1.1",
                headerFields: headers
            )!
            client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
            client?.urlProtocol(self, didLoad: body)
            client?.urlProtocolDidFinishLoading(self)
        }
    }
#endif  // !os(Linux)

